INSERT IGNORE INTO `cms_page_translations` (`id`, `cms_page_id`, `language_id`, `title`, `content`, `meta_title`, `meta_description`, `alternate_page_title`, `translation_status`, `translated_at`, `created_at`, `updated_at`) VALUES (21, 7, 3, 'Résultats de recherche', '[plugin:live-search-2026 mode=results]', 'Résultats de recherche', 'Résultats de recherche multi-contenu à travers les produits, les pages CMS, les articles de la base de connaissances et les témoignages de clients.', NULL, 'ai_translated', '2026-08-10 16:35:34', '2026-08-04 16:29:55', '2026-08-10 16:35:37');
