        // Table: cms_page_translations (excl page 13)
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `cms_page_translations` (`id`, `cms_page_id`, `language_id`, `title`, `content`, `meta_title`, `meta_description`, `alternate_page_title`, `translation_status`, `translated_at`, `created_at`, `updated_at`) VALUES (22, 13, 3, 'Page d\'achat post-webinaire et guide d\'exemple', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h1>Accès vidéo sécurisé &amp; Intégration</h1>\n<p>Cette page contient du contenu acheté et est protégée par des contrôles d\'accès (mot de passe et/ou vérification de commande). L\'exemple ci-dessous utilise une démo publique de Vimeo uniquement à des fins de démonstration. Pour la production, choisissez une méthode de livraison sécurisée qui correspond à vos exigences en matière de confidentialité et de streaming.</p>\n<p>[code-embed:1]</p>\n<h2>Options d\'intégration</h2>\n<ul>\n<li><strong>Fournisseur de vidéo hébergée (recommandé dans la plupart des cas) utilisant la fonctionnalité CODE EMBED,</strong><br>Utilisez un fournisseur tel que Vimeo ou Wistia et activez les restrictions d\'intégration au niveau du domaine afin que la vidéo ne soit lue que sur votre site. Ces fournisseurs offrent également des options de confidentialité, d\'analytique et de streaming adaptatif dès le départ.</li>\n<li><strong>URLs signées locales ou s3 (haute sécurité) - Utilisation de la fonctionnalité Téléchargements du CMS</strong><br>Stockez des fichiers sur un disque local ou dans S3 et livrez-les en utilisant des URLs signées à durée limitée. Cela empêche les téléchargements non autorisés et les liens directs.</li>\n</ul>\n<h2>Comment mettre en œuvre</h2>\n<ol>\n<li>Assurez-vous que la page impose une vérification de mot de passe et de commande avant de rendre le lecteur.</li>\n<li>Choisissez une méthode d\'hébergement (fournisseur hébergé, S3 + CDN, ou fichiers protégés par le CMS) en fonction de vos besoins en matière de sécurité et de votre budget.</li>\n<li>Configurez les contrôles d\'accès :\n<ul>\n<li>Fournisseur : activez les restrictions au niveau du domaine et les liens privés.</li>\n<li>S3/CDN : configurez des URLs signées et de courtes expirations.</li>\n<li>CMS : activez le filtrage des fichiers lié aux commandes ou aux sessions utilisateur.</li>\n</ul>\n</li>\n<li>Intégrez le lecteur :\n<ul>\n<li>Utilisez le code d\'intégration du fournisseur.</li>\n<li>Ou insérez le composant de téléchargements/intégration du CMS pour diffuser des fichiers protégés.</li>\n</ul>\n</li>\n<li>Cette page est configurée pour être \'<strong>Exclure de la recherche</strong>\' dans les options de publication, ce qui est le paramètre recommandé pour les pages sécurisées (filtrées).</li>\n<li>Testez minutieusement en préproduction pour éviter tout accès non autorisé et le partage de votre contenu &mdash; confirmez que la vidéo ne se lit que depuis le(s) domaine(s) autorisé(s) et que seuls les utilisateurs ayant acheté peuvent voir et/ou utiliser un code d\'accès.</li>\n</ol>\n</div>', 'Page d\'achat post-achat d\'échantillon de webinaire et de guide', NULL, NULL, 'ai_translated', '2026-08-10 16:35:37', '2026-08-04 16:30:04', '2026-08-10 16:35:45');
SQL
);

        // Table: cms_page_translations (excl page 13)
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `cms_page_translations` (`id`, `cms_page_id`, `language_id`, `title`, `content`, `meta_title`, `meta_description`, `alternate_page_title`, `translation_status`, `translated_at`, `created_at`, `updated_at`) VALUES (24, 16, 3, 'Contactez-nous', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<p style=\"text-align: center;\">Veuillez remplir le formulaire ci-dessous pour nous contacter par e-mail :</p>\n<div style=\"width: 100%; max-width: 600px; margin: 0 auto;\">[cms-form id=1]</div>\n<p>&nbsp;</p>\n</div>', 'Contactez', NULL, NULL, 'ai_translated', '2026-08-10 16:35:45', '2026-08-04 16:30:09', '2026-08-10 16:35:48');
