        // Table: cms_page_translations (excl page 13)
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `cms_page_translations` (`id`, `cms_page_id`, `language_id`, `title`, `content`, `meta_title`, `meta_description`, `alternate_page_title`, `translation_status`, `translated_at`, `created_at`, `updated_at`) VALUES (40, 19, 3, 'Vérifier le statut de la commande', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<p style=\"text-align: center;\">&nbsp;</p>\n</div>\n<p style=\"text-align: center;\">[plugin:order-tracker-2026]</p>\n<p>&nbsp;</p>', 'Vérifier le statut de la commande', 'Vérifier le statut de la commande', NULL, 'ai_translated', '2026-08-10 16:36:09', '2026-08-06 15:28:59', '2026-08-10 16:36:13');
