INSERT IGNORE INTO `cms_pages` (`id`, `title`, `slug`, `content`, `meta_title`, `meta_description`, `cms_search_index`, `cms_search_index_locked`, `author_id`, `expires_at`, `requires_code`, `access_code`, `required_product_id`, `custom_css`, `custom_js`, `header_image`, `background_image`, `background_video`, `background_video_url`, `background_video_type`, `background_video_s3`, `background_video_region`, `background_video_bucket_name`, `background_video_access_key_id`, `background_video_secret_access_key`, `background_video_cdn_url`, `alternate_page_title`, `page_title_alignment`, `page_title_css`, `include_slideshow`, `min_header_height`, `is_active`, `exclude_from_search`, `page_type`, `page_ranking`, `hide_page_ranking`, `custom_sorting`, `layout_type`, `left_col`, `right_col`, `custom_author`, `show_author`, `show_title`, `show_date`, `featured_image`, `featured_image_s3`, `featured_image_region`, `featured_image_bucket_name`, `featured_image_access_key_id`, `featured_image_secret_access_key`, `media_image_s3`, `media_image_region`, `media_image_bucket_name`, `media_image_access_key_id`, `media_image_secret_access_key`, `featured_image_cdn_url`, `media_image_cdn_url`, `created_at`, `updated_at`) VALUES (13, 'Webinar & Guidebook Sample Post Purchase Page', 'webinar-guidebook-ordered', '<div class=\"prose prose-slate max-w-none\" style=\"max-width: none !important; width: 100%;\">\n<h1>Secure Video Access &amp; Embedding</h1>\n<p>This page contains purchased content and is protected by access controls (password and/or order verification). The sample below uses a public Vimeo demo for demonstration only. For production, choose a secure delivery method that matches your privacy and streaming requirements.</p>\n<p>[code-embed:1]</p>\n<h2>Embedding options</h2>\n<ul>\n<li><strong>Hosted video provider (recommended for most cases) using the CODE EMBED feature,</strong><br>Use a provider such as Vimeo or Wistia and enable domain-level embed restrictions so the video plays only on your site. These providers also offer privacy, analytics, and adaptive streaming out of the box.</li>\n<li><strong>Local or s3 signed URLs (high security) - Using the CMS Downloads Feature</strong><br>Store files on local drive or in S3 and deliver using time-limited signed URLs. This prevents unauthorized downloads and direct linking.</li>\n</ul>\n<h2>How to implement</h2>\n<ol>\n<li>Ensure the page enforces password and order verification before rendering the player.</li>\n<li>Choose a hosting method (hosted provider, S3 + CDN, or CMS protected files) based on your security needs and budget.</li>\n<li>Configure access controls:\n<ul>\n<li>Provider: enable domain-level restrictions and private links.</li>\n<li>S3/CDN: configure signed URLs and short expirations.</li>\n<li>CMS: enable file gating tied to orders or user sessions.</li>\n</ul>\n</li>\n<li>Embed the player:\n<ul>\n<li>Use the provider&rsquo;s embed code.</li>\n<li>Or insert the CMS downloads/embed component to stream protected files.</li>\n</ul>\n</li>\n<li>This page is set to be \'<strong>Exclude From Search</strong>\' under the publishing options which is the recommended setting for secured (gated) pages.</li>\n<li>Test thoroughly in staging to prevent unauthorized access and sharing of your content &mdash; confirm the video only plays from allowed domain(s) and that only the purchased users can view and/or with an access code.</li>\n</ol>\n</div>', 'Webinar & Guidebook Sample Post Purchase Page', '', '', 1, NULL, NULL, 1, 'demo12345#', 15, '', '', NULL, NULL, NULL, NULL, 'local', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'middle-center', NULL, NULL, '320px', 0, 1, 1, 0, 1, 0, 1, '', '', NULL, 0, 0, 0, NULL, 0, NULL, NULL, NULL, NULL, 1, NULL, NULL, 'admin@support.local', 'X5LvXKvyxBbfZGD!', NULL, 'https://d23w3zagfzgqcb.cloudfront.net', '2026-07-26 13:12:45', '2026-08-02 14:01:17');
SQL
);

