        // Table: email_template_translations
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `email_template_translations` (`id`, `email_template_id`, `language_id`, `subject`, `header_html`, `salutation`, `greeting`, `body`, `sign_off`, `signature`, `disclaimer`, `copyright`, `footer_html`, `translation_status`, `translated_at`, `created_at`, `updated_at`) VALUES (1, 1, 2, 'Confirmación de Pedido # {{order_id}}', NULL, 'Estimado/a {{customer_name}},', '<p><strong>¡Agradecemos su pedido!</strong></p><p>Si necesita asistencia, por favor envíe un ticket de soporte o mándenos un correo electrónico.</p>', '<p>A continuación se detallan los datos de su pedido.</p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta sobre este pedido, ¡no dude en contactarnos en cualquier momento!', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:14', '2026-07-29 12:54:58', '2026-08-10 16:27:19');
SQL
);

        // Table: email_template_translations
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `email_template_translations` (`id`, `email_template_id`, `language_id`, `subject`, `header_html`, `salutation`, `greeting`, `body`, `sign_off`, `signature`, `disclaimer`, `copyright`, `footer_html`, `translation_status`, `translated_at`, `created_at`, `updated_at`) VALUES (2, 2, 2, 'Confirmación de Envío de Pedido en Línea # {{order_id}}', NULL, 'Estimado/a {{customer_name}},', '<p>Este es un mensaje de notificación de envío. ¡Su pedido ha sido enviado!</p>', '<p>Número de seguimiento: {{tracking_number}}</p><p>{{order_items_table}}</p>', 'Atentamente,', 'Departamento de Ventas', 'Si tiene alguna pregunta sobre su pedido, no dude en ponerse en contacto con nosotros.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:19', '2026-07-29 12:55:04', '2026-08-10 16:27:24');
SQL
);

        // Table: email_template_translations
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `email_template_translations` (`id`, `email_template_id`, `language_id`, `subject`, `header_html`, `salutation`, `greeting`, `body`, `sign_off`, `signature`, `disclaimer`, `copyright`, `footer_html`, `translation_status`, `translated_at`, `created_at`, `updated_at`) VALUES (3, 3, 2, 'Recordatorio de descarga -- ID de pedido # {{order_id}}', NULL, 'Estimado/a {{customer_name}},', '<p><strong>Solo queríamos recordarte que descargues tu(s) producto(s) que ordenaste recientemente.</strong></p>', '<p>Puedes acceder a tu(s) enlace(s) de descarga a continuación:</p><p>{{download_links}}</p><p>{{order_items_table}}</p>', 'Atentamente,', 'Equipo de Soporte al Cliente', 'Las descargas expiran en 7 días.', 'Copyright 2026', NULL, 'ai_translated', '2026-08-10 16:27:24', '2026-07-29 12:55:12', '2026-08-10 16:27:30');
SQL
);

        // Table: email_template_translations
        DB::unprepared(<<<'SQL'
