        // Table: plugins
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `plugins` (`id`, `api_id`, `name`, `version`, `type`, `author`, `filename`, `install_type`, `description`, `shortcode`, `activation_required`, `activation_instructions`, `activation_failed_msg`, `activation_success_msg`, `usage_instructions`, `help_info`, `help_url`, `activation_date`, `activation_status`, `activation_key`, `serial_number`, `created_at`, `updated_at`) VALUES (1, NULL, 'Slideshow - Swiper Display (2026)', '1.0', 'display', 'Built-in', 'slideshow_2026', 1, 'Displays an active slideshow using Swiper.js with full overlay content controls, flexible alignment, and CSS customizations.', 'slideshow-2026', 'no', NULL, NULL, NULL, '<p>Add the shortcode <strong>[plugin:slideshow-2026]</strong> to any CMS page to display your slideshow. To specify a slideshow by ID use: <strong>[plugin:slideshow-2026 id=2]</strong>. To disable navigation arrows: <strong>[plugin:slideshow-2026 nav=off]</strong>. To disable pagination dots: <strong>[plugin:slideshow-2026 paging=off]</strong>.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
SQL
);

        // Table: plugins
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `plugins` (`id`, `api_id`, `name`, `version`, `type`, `author`, `filename`, `install_type`, `description`, `shortcode`, `activation_required`, `activation_instructions`, `activation_failed_msg`, `activation_success_msg`, `usage_instructions`, `help_info`, `help_url`, `activation_date`, `activation_status`, `activation_key`, `serial_number`, `created_at`, `updated_at`) VALUES (2, NULL, 'Shipping Rates - FedEx REST API (2026)', '1.0', 'shipping', 'Built-in', 'fedex_api_2026', 1, 'Live FedEx shipping rates via the FedEx REST API v1 for North American and International shipments.', 'fedex-api', 'no', NULL, NULL, NULL, '<p>Enter your FedEx API credentials below. You need a FedEx developer account with REST API credentials (Client ID and Client Secret). Visit <a href=\"https://developer.fedex.com\" target=\"_blank\">developer.fedex.com</a>. Note: This uses FedEx REST API v1 — old SOAP credentials are not compatible.</p>', NULL, NULL, NULL, 0, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
SQL
);

        // Table: plugins
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `plugins` (`id`, `api_id`, `name`, `version`, `type`, `author`, `filename`, `install_type`, `description`, `shortcode`, `activation_required`, `activation_instructions`, `activation_failed_msg`, `activation_success_msg`, `usage_instructions`, `help_info`, `help_url`, `activation_date`, `activation_status`, `activation_key`, `serial_number`, `created_at`, `updated_at`) VALUES (3, NULL, 'Shipping Rates - UPS REST API (2026)', '1.0', 'shipping', 'Built-in', 'ups_api_2026', 1, 'Real-time UPS shipping rates via the UPS REST Rating API with OAuth2. Supports all domestic and international UPS services.', 'ups-api', 'yes', '<p>Enter your <strong>UPS Client ID</strong> and <strong>Client Secret</strong> from <a href=\"https://developer.ups.com\" target=\"_blank\">developer.ups.com</a> and click Activate. Your UPS Account Number is optional but required for negotiated rates.</p>', 'Could not activate. Please check your UPS Client ID and Client Secret.', 'UPS plugin activated. Configure your services in the Settings tab.', '<p>Active UPS shipping rates will automatically appear on the checkout review page alongside other shipping options, sorted by price. No shortcode required for shipping plugins.</p>', NULL, 'https://developer.ups.com/api/reference/rating/business-rules', NULL, 0, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
SQL
);

        // Table: plugins
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `plugins` (`id`, `api_id`, `name`, `version`, `type`, `author`, `filename`, `install_type`, `description`, `shortcode`, `activation_required`, `activation_instructions`, `activation_failed_msg`, `activation_success_msg`, `usage_instructions`, `help_info`, `help_url`, `activation_date`, `activation_status`, `activation_key`, `serial_number`, `created_at`, `updated_at`) VALUES (4, NULL, 'Shipping Rates - USPS REST API v3 (2026)', '1.0', 'shipping', 'Built-in', 'usps_api_2026', 1, 'Real-time USPS shipping rates via the new USPS REST API v3 with OAuth2. Replaces the deprecated SOAP Web Tools. Supports Priority Mail, Ground Advantage, First-Class, and international services.', 'usps-api', 'yes', '<p>Register at <a href=\"https://developer.usps.com\" target=\"_blank\">developer.usps.com</a>, create an application, and copy your <strong>Client ID</strong> and <strong>Client Secret</strong>. Enter them below and click Activate.</p><p><em>Note: The old USPS Web Tools XML API was deprecated January 2024. This plugin uses the new REST API.</em></p>', 'Could not activate. Please verify your USPS Client ID and Client Secret.', 'USPS plugin activated. Enable your desired services in the Settings tab.', '<p>Active USPS shipping rates will automatically appear on the checkout review page alongside other shipping options, sorted by price. No shortcode required for shipping plugins.</p>', NULL, 'https://developer.usps.com/api/81', NULL, 0, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
SQL
);

        // Table: plugins
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `plugins` (`id`, `api_id`, `name`, `version`, `type`, `author`, `filename`, `install_type`, `description`, `shortcode`, `activation_required`, `activation_instructions`, `activation_failed_msg`, `activation_success_msg`, `usage_instructions`, `help_info`, `help_url`, `activation_date`, `activation_status`, `activation_key`, `serial_number`, `created_at`, `updated_at`) VALUES (5, NULL, 'Featured Items Display (2026)', '1.0', 'display', 'Built-in', 'featured_items_2026', 1, 'Displays products that have the Featured Item flag enabled. Supports grid, list, and Swiper slider display modes. Shortcode: [plugin:featured-items]', 'featured-items', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:featured-items]</strong> to any CMS page to display your featured products. Available parameters:</p><ul><li><strong>display</strong> — <code>grid</code> (default), <code>list</code>, or <code>slider</code></li><li><strong>max</strong> — maximum number of products to show (default: 12)</li><li><strong>cols</strong> — grid columns 2–6 (default: 4, grid mode only)</li><li><strong>sort</strong> — <code>random</code>, <code>newest</code>, or <code>name</code></li><li><strong>header</strong> — optional section title text</li><li><strong>slides</strong> — visible slides at desktop (default: 4, slider mode only)</li><li><strong>nav</strong> — <code>on</code> / <code>off</code> navigation arrows (slider mode)</li><li><strong>autoplay</strong> — <code>on</code> / <code>off</code> (slider mode)</li><li><strong>speed</strong> — autoplay delay in ms (default: 4000, slider mode)</li></ul><p>To mark a product as featured, open the product in Admin → Edit → Advanced Settings and enable the ★ Featured Item toggle, then save.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
SQL
);

        // Table: plugins
        DB::unprepared(<<<'SQL'
INSERT IGNORE INTO `plugins` (`id`, `api_id`, `name`, `version`, `type`, `author`, `filename`, `install_type`, `description`, `shortcode`, `activation_required`, `activation_instructions`, `activation_failed_msg`, `activation_success_msg`, `usage_instructions`, `help_info`, `help_url`, `activation_date`, `activation_status`, `activation_key`, `serial_number`, `created_at`, `updated_at`) VALUES (6, NULL, 'Cross-Sell List Display (2026)', '1.0', 'display', 'Built-in', 'cross_sell_list_2026', 1, 'Displays the cross-selling products linked to a specific product. Filter by Product ID. Supports grid, list, and Swiper slider display modes. Shortcode: [plugin:cross-sell-list product_id=X]', 'cross-sell-list', 'no', NULL, NULL, NULL, '<p>Add <strong>[plugin:cross-sell-list product_id=X]</strong> to any CMS page to display the cross-sell products for a given product. Replace <code>X</code> with the numeric product ID. Available parameters:</p><ul><li><strong>product_id</strong> — the product whose cross-sells to display (required)</li><li><strong>display</strong> — <code>grid</code> (default), <code>list</code>, or <code>slider</code></li><li><strong>max</strong> — maximum number of products to show (default: 12)</li><li><strong>cols</strong> — grid columns 2–6 (default: 4, grid mode only)</li><li><strong>sort</strong> — <code>sort_order</code> (default), <code>newest</code>, or <code>name</code></li><li><strong>header</strong> — optional section title text</li><li><strong>slides</strong> — visible slides at desktop (default: 4, slider mode only)</li><li><strong>nav</strong> — <code>on</code> / <code>off</code> navigation arrows (slider mode)</li><li><strong>autoplay</strong> — <code>on</code> / <code>off</code> (slider mode)</li><li><strong>speed</strong> — autoplay delay in ms (default: 4000, slider mode)</li></ul><p>Cross-sells are managed per product under Admin → Edit Product → Cross-Selling. Only items with <em>Display on Item View</em> enabled will appear.</p>', NULL, NULL, NULL, 1, NULL, NULL, '2026-08-10 01:52:56', '2026-08-10 01:52:56');
SQL
);

        // Table: plugins
